# Installer: step 8 (Installer), step 7 (InstallerDrivers), steps 10/11 (InstallerDisk), step 14 (InstallerSummary).
from gen import *
from b3 import device_table, driverless_hint
W, H = 320, 200
STEPS = ['اللغة', 'تسهيلات الاستخدام', 'لوحة المفاتيح', 'الشبكة', 'تجربة أو تثبيت', 'نوع التثبيت', 'العتاد والتعريفات', 'المكوّنات', 'إضافات', 'القرص', 'التشفير', 'الحساب', 'المنطقة الزمنية', 'الملخّص', 'التثبيت', 'اكتمل التثبيت']
def frame(current, title, lead, content, foot_info='', next_label='التالي', next_state='', also=(), head_end=''):
    def st(i, s):
        cur = (i == current) or (i in also); done = i < current
        dot = f'<span style="width: {ic_l}; height: {ic_l}; flex: none; border-radius: {r_round}; display: inline-flex; align-items: center; justify-content: center; font-size: {f12}; font-weight: {w7}; background: {t.acc if cur else "transparent"}; color: {t.onacc if cur else (t.ok if done else t.mute)}; border: {HAIR} solid {t.acctext if cur else (t.ok if done else t.ctl)}; box-sizing: border-box">{ic("check", True) if done else i + 1}</span>'
        inner = f'{dot}<span>{tx(s)}</span>' + (f'<span style="font-size: {f12}; color: {t.mute}">مكتمل</span>' if done else '')
        css = f'width: 100%; height: {tgt}; padding: 0 {s2}; box-sizing: border-box; border-radius: {r_ctl}; display: flex; align-items: center; gap: {s3}; color: {t.text if (cur or done) else t.mute}; font-weight: {w7 if cur else w4}'
        if done: return f'<li><button{act("installer.step", f"الخطوة {i + 1}: {s}")} aria-label="الخطوة {i + 1}: {s} (مكتمل)" style="{css}">{inner}</button></li>'
        return f'<li{" aria-current=\"step\"" if cur else ""} style="{css}">{inner}</li>'
    side = f'<nav aria-label="خطوات التثبيت" style="width: {g(64)}; flex: none; padding: {s5} {s4}; box-sizing: border-box; background: {t.bar}; border-inline-end: {HAIR} solid {t.line}; display: flex; flex-direction: column; gap: {s4}"><div style="display: flex; align-items: center; gap: {s2}; font-family: {FF_TITLE}; font-weight: {w7}">{mark()}<span>{tx("تثبيت Ultar OS")}</span></div><ol style="display: flex; flex-direction: column; gap: {s1}">{"".join(st(i, s) for i, s in enumerate(STEPS))}</ol></nav>'
    foot = f'<footer style="height: {g(16)}; flex: none; padding: 0 {s6}; display: flex; align-items: center; gap: {s2}; border-top: {HAIR} solid {t.line}; background: {t.bar}">{button("إلغاء التثبيت", "installer.cancel", "quiet")}<div style="flex: 1; padding: 0 {s4}">{foot_info}</div>{button("السابق", "installer.prev")}{button(next_label, "installer.next", "primary", next_state)}</footer>'
    main = f'<main style="flex: 1; display: flex; flex-direction: column; min-width: 0"><div style="flex: 1; padding: {s5} {s6}; box-sizing: border-box; overflow: hidden; display: flex; flex-direction: column; gap: {s4}"><div style="display: flex; align-items: flex-end; gap: {s2}"><div style="flex: 1">{h1(title)}<div style="color: {t.mute}">{tx(lead)}</div></div>{head_end}</div>{content}</div>{foot}</main>'
    return f'<div style="position: absolute; inset: 0; display: flex; background: {t.ground}">{side}{main}</div>'
SIZE_NOTE = '— = الحجم يُحسب من وسيط التثبيت والقرص عند التشغيل؛ لا قيمة له في المواصفة.'
size = lambda: f'<span style="font-size: {f12}; color: {t.mute}" aria-label="الحجم غير محدَّد بعد">{NA}</span>'

begin('Installer.dc.html')
COMPS = [('office', 'الأدوات المكتبية', 'مستندات، جداول، عروض، أدوات PDF', True, None), ('code', 'المبرمج', 'محرر شيفرة، Git، أدوات Rust و C و Python', True, None), ('media', 'الوسائط', 'موسيقى، فيديو، إدارة الصور وتحريرها', False, None), ('mail', 'التواصل', 'بريد، تقويم، جهات اتصال، مكالمات فيديو', False, None),
    ('mesh', 'الترابط', 'ربط أجهزتك: الشاشة والملفات والقدرة الحاسوبية', False, None), ('spark', 'المساعد والذكاء الاصطناعي المحلي', 'مساعد صوتي ونماذج تعمل على جهازك', True, ('info', 'موصى به لهذا الجهاز')), ('package', 'برامج Linux', 'تثبيت حزم ‎.deb‎ في منطقة معزولة', True, ('info', 'يتطلّبه Firefox')), ('firefox', 'Firefox', 'متصفح احتياطي للمواقع التي لا تعمل بعد في متصفح Ultar', True, None),
    ('windows', 'برامج Windows', 'تشغيل ‎.exe‎ و ‎.msi‎ في خلية معزولة', False, None), ('android', 'تطبيقات Android', 'بيئة تشغيل معزولة', False, None), ('server', 'الحاويات والخادم', 'خلايا، إدارة عبر الويب، خادم SSH', False, None), ('remote', 'الوصول عن بُعد', 'عرض الشاشة والتحكّم بها', False, None)]
def comp(icon, name, text, on, tag):
    end = f'<span style="display: inline-flex; align-items: center; gap: {s2}">{badge(tag[1], tag[0], "info") if tag else ""}{size()}</span>'
    return checkrow(name, 'installer.component', on, text, end=end, icon=icon)
scope = radiogroup('حجم التثبيت', radiocard('الأساسي', 'النظام والتطبيقات الأساسية فقط', False, 'installer.scope') + radiocard('الموسّع', 'الأساسي مع الأدوات المكتبية والوسائط والتواصل و Firefox', False, 'installer.scope') + radiocard('اختيار مخصّص', 'اختر المكوّنات واحداً واحداً', True, 'installer.scope'))
lst = card(f'<div role="group" aria-label="المكوّنات" style="display: grid; grid-template-columns: 1fr 1fr; gap: {s1} {s4}; padding: {s2}">{"".join(comp(*c) for c in COMPS)}</div>')
info = f'<div><div><span style="font-weight: {w7}">المجموع: {NA}</span><span style="color: {t.mute}"> · المتاح على القرص: {NA}</span></div>{sub(SIZE_NOTE)}</div>'
out('Ultar OS – التثبيت: المكوّنات', W, H, frame(7, 'ما الذي تريد تثبيته؟', 'يمكنك إضافة أي مكوّن أو إزالته لاحقاً من متجر Ultar، دون إعادة تثبيت النظام.', scope + lst, info), 'Installation · Schritt 8 Umfang und Komponenten', 3)

begin('InstallerDrivers.dc.html')
tools = f'{button("جلب تعريفات أحدث", "installer.drivers.fetch", icon="download")}{button("حفظ مخطّط العتاد", "installer.drivers.plan", name="حفظ مخطّط العتاد لكل الأجهزة")}'
out('Ultar OS – التثبيت: العتاد والتعريفات', W, H, frame(6, 'العتاد والتعريفات', 'التعريفات كلها من وسيط التثبيت وتُختبر الآن على جهازك.', driverless_hint() + device_table('installer.drivers', False), sub('7 أجهزة تعمل · جهاز واحد بلا تعريف · يمكنك المتابعة'), head_end=tools), 'Installation · Schritt 7 Hardware & Treiber', 3)

begin('InstallerDisk.dc.html')
part = f'<span style="display: block; padding-top: {s2}"><span role="img" aria-label="تقسيم القرص: Windows 11 ثم Ultar OS" style="display: flex; height: {ic_l}; border-radius: {r_ctl}; overflow: hidden; border: {HAIR} solid {t.ctl}"><span style="flex: 3; background: {t.raised}; display: flex; align-items: center; justify-content: center; font-size: {f12}">{ltr("Windows 11")} · {NA}</span><span style="flex: 2; background: {t.hover}; border-inline-start: {RING} solid {t.acctext}; display: flex; align-items: center; justify-content: center; font-size: {f12}">{ltr("Ultar OS")} · {NA}</span></span></span>'
disk = card(cardhead('القرص', 'الأنظمة الموجودة تُكتشف ولا تُمسّ إلا باختيارك الصريح.', select('Samsung SSD 980 · ' + NA, 'القرص', 'installer.disk.select')) + f'<div style="padding: {s4}; display: flex; flex-direction: column; gap: {s3}">' + radiogroup('طريقة استخدام القرص', radiocard('استخدام القرص كاملاً', 'يُمحى كل ما على القرص، ومنه Windows 11.', False, 'installer.disk.mode', False) + radiocard('بجانب النظام الموجود', 'يبقى Windows 11 كما هو، ويأخذ Ultar OS جزءاً من المساحة الفارغة.', True, 'installer.disk.mode', False, part) + radiocard('يدوي', 'الأقسام ونقاط الضمّ ونظام الملفات وقسم الإقلاع.', False, 'installer.disk.mode', False), True) + slider('المساحة المخصّصة لـ Ultar OS', 40, 'installer.disk.share') + note(SIZE_NOTE) + '</div>', grow=True)
tpm = f'<div aria-disabled="true" style="padding: {s3}; border-radius: {r_card}; border: {HAIR} solid {t.line}; color: {t.ctl}; display: flex; gap: {s3}"><span style="width: {ic_l}; height: {ic_l}; flex: none; border-radius: {r_round}; border: {HAIR} solid {t.line}; box-sizing: border-box"></span><div><div style="font-weight: {w6}">{tx("شريحة الجهاز (TPM) مع مفتاح استعادة")}</div><div style="font-size: {f12}; color: {t.mute}">{tx("غير متاحة على هذا الجهاز: شريحة TPM معطّلة في إعدادات اللوحة الأم.")}</div></div></div>'
pwd = f'<span style="display: flex; flex-direction: column; gap: {s2}; padding-top: {s2}"><span style="display: flex; align-items: flex-end; gap: {s2}">{field("عبارة المرور", "installer.enc.pass", kind="password", value="••••••••••••")}{ibtn("إظهار عبارة المرور", "eye", "installer.enc.show")}</span>{field("تكرار عبارة المرور", "installer.enc.pass", kind="password", value="••••••••", state="error", error="العبارتان غير متطابقتين.")}</span>'
enc = card(cardhead('التشفير', 'يحمي بياناتك إذا ضاع الجهاز أو سُرق.') + f'<div style="padding: {s4}; display: flex; flex-direction: column; gap: {s3}">' + radiogroup('التشفير', radiocard('بلا تشفير', 'يستطيع من يصل إلى القرص قراءة ملفاتك.', False, 'installer.enc.mode', False) + radiocard('عبارة مرور', 'تُطلب عند كل إقلاع. لا يمكن استرجاع البيانات من دونها.', True, 'installer.enc.mode', False), True) + pwd + tpm + '</div>', grow=True)
out('Ultar OS – التثبيت: القرص والتشفير', W, H, frame(9, 'القرص والتشفير', 'أين يُثبَّت Ultar OS، وهل تُشفَّر بياناتك؟ (الخطوتان 10 و 11 معروضتان معاً في هذه اللوحة.)', f'<div style="display: flex; gap: {s4}; align-items: flex-start">{disk}{enc}</div>', sub('لن يُكتب شيء على القرص قبل تأكيدك في الملخّص.'), next_state='disabled', also=(10,)), 'Installation · Schritt 10/11 Platte und Verschlüsselung', 3)

begin('InstallerSummary.dc.html')
def srow(label, value, last=False):
    return row(label, '', f'<span style="display: inline-flex; align-items: center; gap: {s3}"><span style="color: {t.mute}">{tx(value)}</span>{button("تعديل", "installer.edit", "quiet", name="تعديل: " + label)}</span>', last)
summary = card(srow('اللغة ولوحة المفاتيح', 'العربية · العربية + الإنجليزية') + srow('الشبكة', 'واي فاي KM-Office') + srow('المكوّنات', 'الأدوات المكتبية، المبرمج، المساعد، برامج Linux، Firefox') + srow('التشفير', 'عبارة مرور') + srow('الحساب', 'أنس · anas · ultar-pc') + srow('المنطقة الزمنية', 'دمشق · 24 ساعة', True))
erase = f'<section role="alert" aria-label="ما الذي سيُمحى" style="border-radius: {r_card}; background: {t.raised}; border: {RING} solid {t.danger}; padding: {s4}; display: flex; flex-direction: column; gap: {s3}"><div style="display: flex; align-items: center; gap: {s3}; color: {t.danger}">{ic("error")}{h2("ما الذي سيُمحى")}</div><ul role="list" style="display: flex; flex-direction: column; gap: {s1}"><li style="display: flex; gap: {s2}"><span style="font-weight: {w7}">{tx("القرص Samsung SSD 980")} · {NA}</span><span>{tx("يُمحى كاملاً.")}</span></li><li>{tx("يُحذف منه: Windows 11 وكل الملفات والبرامج.")}</li><li>{tx("لا يتأثّر: ذاكرة USB وأي قرص آخر.")}</li></ul>{checkrow("أفهم أن هذه البيانات ستُمحى ولا يمكن استرجاعها.", "installer.confirm", False)}</section>'
out('Ultar OS – التثبيت: الملخّص', W, H, frame(13, 'الملخّص', 'راجع اختياراتك. هذه آخر خطوة قبل الكتابة على القرص.', summary + erase, sub('زر «تثبيت» يُفعَّل بعد وضع العلامة على سطر المحو. ' + SIZE_NOTE), next_label='تثبيت', next_state='disabled'), 'Installation · Schritt 14 Zusammenfassung (was gelöscht wird)', 3)
